"use client";

import type { ImageLoaderProps } from "next/image";

// Matches the sizes generated by scripts/export-preview.mjs; no external CDN needed.
export default function staticImageLoader({ src, width }: ImageLoaderProps) {
  const match = src.match(
    /^(.*)\/images\/(architecture|interior|balcony|terrace)\.webp$/,
  );
  if (!match) return src;
  const size = [480, 768, 1200, 1920].find((size) => size >= width) ?? 1920;
  return `${match[1]}/images/responsive/${match[2]}-${size}.webp`;
}
